-- 003_soil_grid.sql
-- ตาราง lookup ค่าดิน OM/P/K ราย grid cell (0.05 องศา, WGS84)
-- grid 166x292  origin_left=97.326805949  origin_top=20.312281681  px=0.05
-- valid cells = 17354
-- คลิกจุด: grid_col=floor((lng-origin_left)/px), grid_row=floor((origin_top-lat)/px)

drop table if exists public.soil_grid;
create table public.soil_grid (
  grid_row smallint not null,
  grid_col smallint not null,
  om real,
  p  real,
  k  real,
  primary key (grid_row, grid_col)
);

alter table public.soil_grid enable row level security;
create policy "soil_grid: read for all" on public.soil_grid for select using (true);
-- table-level GRANT (Supabase ต้องมีทั้ง RLS policy + GRANT)
grant select on public.soil_grid to anon, authenticated;

